"import os\nimport re\n\npatterns = [r'\\bdemo\\b', r'\\bmock\\b', r'\\bjudges\\b', r'\\bhackathon\\b', r'\\bsimulation\\b', r'\\bdummy\\b', r'\\bsample\\b']\nregexes = [re.compile(p, re.IGNORECASE) for p in patterns]\n\nlib_dir = r\"c:\\Women\\she_shield\\lib\"\nfor root, dirs, files in os.walk(lib_dir):\n    for file in files:\n        if file.endswith('.dart'):\n            filepath = os.path.join(root, file)\n            with open(filepath, 'r', encoding='utf-8') as f:\n                content = f.read()\n            \n            found = []\n            for r in regexes:\n                matches = r.findall(content)\n                if matches:\n                    found.append(f\"{r.pattern}: {len(matches)}\")\n            if found:\n                print(f\"File: {os.path.relpath(filepath, lib_dir)} - matches: {', '.join(found)}\")\n"